style.css:
@-moz-document domain("bondipathshala.education") {
/* ===========================
   BONDI PATHSHALA AESTHETIC DARK
   Premium Ed-Tech Theme
   =========================== */

:root{
    --bg: #0b1020;
    --bg2: #111827;
    --card: rgba(20, 28, 48, 0.75);
    --card-hover: rgba(30, 41, 59, 0.9);
    --border: rgba(255,255,255,0.08);

    --text: #f3f4f6;
    --text-soft: #cbd5e1;
    --muted: #94a3b8;

    --accent: #60a5fa;
    --accent2: #8b5cf6;

    --glow:
      0 0 20px rgba(96,165,250,.15),
      0 0 40px rgba(139,92,246,.08);
}

/* ===========================
   BODY / GLOBAL
   =========================== */

html,
body{
    background:
    radial-gradient(circle at top left, #16213a 0%, transparent 35%),
    radial-gradient(circle at top right, #1f1b42 0%, transparent 30%),
    linear-gradient(180deg, #0b1020, #0f172a) !important;

    color: var(--text) !important;
}

/* Kill white sections */
section,
main,
header,
footer,
nav,
[class*="section"],
[class*="container"]{
    background: transparent !important;
}

/* ===========================
   TEXT CALIBRATION
   =========================== */

h1,h2,h3,h4,h5,h6{
    color: #ffffff !important;
    letter-spacing: .2px;
}

p,
span,
li,
div,
small,
label{
    color: var(--text-soft) !important;
}

.text-muted,
.text-secondary{
    color: var(--muted) !important;
}

/* ===========================
   GLASS CARDS
   =========================== */

.card,
[class*="card"],
[class*="box"],
.shadow,
.rounded-lg,
.rounded-xl{

    background: var(--card) !important;
    backdrop-filter: blur(18px) saturate(140%);
    -webkit-backdrop-filter: blur(18px);

    border: 1px solid var(--border) !important;
    border-radius: 22px !important;

    box-shadow:
        0 10px 35px rgba(0,0,0,.28),
        inset 0 1px rgba(255,255,255,.04) !important;

    transition: all .25s ease !important;
}

.card:hover,
[class*="card"]:hover{
    background: var(--card-hover) !important;
    transform: translateY(-3px);
    box-shadow:
        0 18px 40px rgba(0,0,0,.35),
        var(--glow) !important;
}

/* ===========================
   NAVBAR
   =========================== */

header,
nav,
[class*="navbar"],
[class*="header"]{

    background:
    rgba(10,15,30,.75) !important;

    backdrop-filter: blur(18px);
    border-bottom:
    1px solid rgba(255,255,255,.06) !important;
}

/* ===========================
   BUTTONS
   =========================== */

button,
.btn,
a[class*="btn"]{

    background:
    linear-gradient(
    135deg,
    rgba(96,165,250,.18),
    rgba(139,92,246,.15)
    ) !important;

    color: white !important;

    border:
    1px solid rgba(255,255,255,.08) !important;

    border-radius: 14px !important;

    transition: .25s ease !important;
}

button:hover,
.btn:hover{

    transform: translateY(-2px);

    background:
    linear-gradient(
    135deg,
    rgba(96,165,250,.28),
    rgba(139,92,246,.25)
    ) !important;

    box-shadow: var(--glow) !important;
}

/* ===========================
   LINKS
   =========================== */

a{
    color: #93c5fd !important;
}

a:hover{
    color: #c4b5fd !important;
}

/* ===========================
   INPUTS
   =========================== */

input,
textarea,
select{

    background:
    rgba(17,24,39,.8) !important;

    color: white !important;

    border:
    1px solid rgba(255,255,255,.08) !important;

    border-radius: 14px !important;
}

input::placeholder,
textarea::placeholder{
    color: #94a3b8 !important;
}

/* ===========================
   FOOTER
   =========================== */

footer{
    background:
    rgba(8,10,20,.9) !important;
}

/* ===========================
   IMAGES
   =========================== */

img,
video,
svg,
canvas,
iframe{
    filter: none !important;
}

/* ===========================
   SCROLLBAR
   =========================== */

::-webkit-scrollbar{
    width: 10px;
}

::-webkit-scrollbar-track{
    background: #0f172a;
}

::-webkit-scrollbar-thumb{
    background:
    linear-gradient(#334155,#475569);
    border-radius: 999px;
}

/* subtle selection color */
::selection{
    background: rgba(96,165,250,.35);
}
}
